#ifndef ZOVUTILS_SHRED_BACKEND_H
#define ZOVUTILS_SHRED_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <stdint.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
static inline int zov_shred_run(int argc,char**argv){int passes=3,remove_file=0,zero=0,verbose=0,exact=0;long long size_override=-1;const char*random_source="/dev/urandom";char**files=(char**)malloc((size_t)(argc+1)*sizeof(char*));if(!files)return 1;int nf=0;for(int i=0;i<argc;i++){const char*a=argv[i];if(!strcmp(a,"--help")){puts("Usage: shred [OPTION]... FILE...\nOverwrite the specified FILE(s) repeatedly, in order to make it harder\nfor even very expensive hardware probing to recover the data.\n  -f, --force           change permissions to allow writing if necessary\n  -n, --iterations=N    overwrite N times instead of the default (3)\n  -s, --size=N          shred this many bytes (suffixes like K, M, G accepted)\n  -u, --remove          deallocate and remove file after overwriting\n  -v, --verbose         show progress\n  -z, --zero            add a final overwrite with zeros\n      --help            display this help and exit\n      --version         output version information and exit");free(files);return 0;}if(!strcmp(a,"--version")){puts("shred (zovutils) 0.10.42");free(files);return 0;}if(!strcmp(a,"-u")||!strcmp(a,"--remove")){remove_file=1;continue;}if(!strcmp(a,"-z")||!strcmp(a,"--zero")){zero=1;continue;}if(!strcmp(a,"-v")||!strcmp(a,"--verbose")){verbose=1;continue;}if(!strcmp(a,"-f")||!strcmp(a,"--force"))continue;if(!strcmp(a,"-x")||!strcmp(a,"--exact")){exact=1;continue;}if(!strncmp(a,"--random-source=",16)){random_source=a+16;continue;}if(!strcmp(a,"--random-source")){if(i+1>=argc){fprintf(stderr,"shred: option requires an argument -- 'random-source'\n");free(files);return 1;}random_source=argv[++i];continue;}if(!strncmp(a,"--size=",7)){char*e;size_override=strtoll(a+7,&e,10);if(*e||size_override<0){free(files);return 1;}continue;}if(!strncmp(a,"--iterations=",13)){char*e;long v=strtol(a+13,&e,10);if(*e||v<0){free(files);return 1;}passes=(int)(v>1000?1000:v);continue;}if(!strcmp(a,"-n")||!strcmp(a,"--iterations")||!strcmp(a,"-s")||!strcmp(a,"--size")){if(i+1>=argc){free(files);return 1;}const char*v=argv[++i];char*e;long long x=strtoll(v,&e,10);if(e==v||x<0){fprintf(stderr,"shred: invalid number of passes: '%s'\n",v);free(files);return 1;}if(*e=='k'||*e=='K')x*=1024;else if(*e=='M')x*=1024*1024;else if(*e=='G')x*=1024LL*1024*1024;else if(*e){fprintf(stderr,"shred: invalid size: '%s'\n",v);free(files);return 1;}if(a[1]=='n'||!strcmp(a,"--iterations"))passes=(int)(x>1000?1000:x);else size_override=x;continue;}if(a[0]=='-'&&strcmp(a,"-")){fprintf(stderr,"shred: unrecognized option '%s'\nTry 'shred --help' for more information.\n",a);free(files);return 1;}files[nf++]=(char*)a;}if(!nf){fprintf(stderr,"shred: missing file operand\nTry 'shred --help' for more information.\n");free(files);return 1;}FILE*rng=fopen(random_source,"rb");if(!rng){fprintf(stderr,"shred: cannot open random source: %s\n",strerror(errno));free(files);return 1;}unsigned char buf[16384];int status=0;for(int fi=0;fi<nf;fi++){const char*path=files[fi];int fd=open(path,O_WRONLY);if(fd<0){fprintf(stderr,"shred: failed to open '%s': %s\n",path,strerror(errno));status=1;continue;}struct stat st;if(fstat(fd,&st)<0){close(fd);status=1;continue;}long long length=size_override>=0?size_override:(long long)st.st_size;if(size_override<0&&!exact&&length%4096)length+=4096-(length%4096);for(int pass=0;pass<passes+(zero?1:0);pass++){if(lseek(fd,0,SEEK_SET)<0){status=1;break;}long long left=length;while(left>0){size_t n=left>(long long)sizeof(buf)?sizeof(buf):(size_t)left;if(zero&&pass==passes)memset(buf,0,n);else if(fread(buf,1,n,rng)!=n){status=1;break;}if(write(fd,buf,n)!=(ssize_t)n){status=1;break;}left-=(long long)n;}if(fsync(fd)<0)status=1;}close(fd);if(verbose)fprintf(stderr,"shred: %s: pass completed\n",path);if(remove_file&&unlink(path)<0){fprintf(stderr,"shred: failed to remove '%s': %s\n",path,strerror(errno));status=1;}}fclose(rng);free(files);return status;}
#endif
